D = [r + s for s in "HDCS" for r in M]
G = [(0, 3)] * 4 + [(1, 4)] * 2 + [(1, 3), (2, 3), (4, 6), (8, 13), (1, 5), (5, 12), (1, 1), (20, 40)]
U = [(i, 0, n) for i, (l, h) in enumerate(G) for n in range(l, h + 1)] + \
