def P(h):
    t = h.split()
    if len(t) != len(set(t)) or not 4 <= len(t) <= 6:
        return None
    V = []
    for x in t:
        if x[-1] not in "HDCS" or x[:-1] not in M:
            return None
        V.append(M.index(x[:-1]) + 1)
    return V, [x[-1] for x in t]

def F(o):
    V, S = o
    r = [a for a, b in zip(V, S) if b in "HD"]
    return [S.count(q) for q in "HDCS"] + [
        len(r), sum(a % 2 < 1 for a in V), sum(a > 10 for a in V), len(set(S)), len(V),
        max(V), min(V), max(V) - min(V), len(V) - len(set(V)), sum(V), sum(r), sum(V) - sum(r)]

def T(f, r):
    i, k, n = r
    v = f[i]
    return v == n if k < 1 else v % n < 1 if k < 2 else v > 1 and all(v % p for p in range(2, v))

def solve(clue):
    E = [P(h) for h in clue.split("\n")]
    if None in E:
        return ""
    X = [F(e) for e in E]
    W = [r for r in U if all(T(f, r) for f in X)]
    if len(W) != 1:
        return ""
    R = W[0]
    used = {x for h in clue.split("\n") for x in h.split()}
    free = [x for x in D if x not in used]
    rr = random.Random(clue)
    for _ in range(60000):
        t = rr.sample(free, rr.choice((4, 5, 6)))
        o = ([M.index(x[:-1]) + 1 for x in t], [x[-1] for x in t])
        if T(F(o), R):
            t.sort(key=lambda x: (M.index(x[:-1]), "HDCS".index(x[-1])))
            return " ".join(t)
    return ""

